export class Orders implements Iterable<Order> {
  readonly #items: Order[] = [];

  add(order: Order): void {
    if (this.#items.length >= MAX_ORDERS) throw new RangeError('order limit reached');
    this.#items.push(order);
  }
  all(): readonly Order[] { return [...this.#items]; }   // type-level read-only copy
  get size(): number { return this.#items.length; }
  [Symbol.iterator](): Iterator<Order> { return this.#items[Symbol.iterator](); }
}
